from typing import Dict, List, Optional, Tuple
from collections import Counter, OrderedDict, defaultdict, deque
import heapq

def unique_paths(m: int, n: int) -> int:
    row = [1] * n
    for _ in range(1, m):
        for c in range(1, n):
            row[c] += row[c - 1]
    return row[-1]
